.slider-container {
    display: flex;
    align-items: center;
    justify-content: center;
    height: 100%;
    margin-bottom: 50px;
}

.slider {
    width: 100%;
    max-width: 100%;
    text-align: center;
    overflow: hidden;
    position: relative;
}
.slides {
    display: flex;
    overflow-x: hidden;
    position: relative;
    scroll-behavior: smooth;
    scroll-snap-type: x mandatory;
    width: 100%;
}
.slide:nth-of-type(even) {
    background-color: rgb(250, 246, 212);
}

.slide {
    display: flex;
    justify-content: center;
    align-items: center;
    flex-shrink: 0;
    width: 100%;
    height: 400px;
    margin-right: 0px;
    box-sizing: border-box;
    background: white;
    transform-origin: center center;
    transform: scale(1);
    scroll-snap-align: center;
    overflow: hidden;
}
.slide .slide-content {
    position: absolute;
    z-index: 2;
    width: 35%;
    bottom: 0;
    left: 0;
    font-weight: 400;
    background: #1f234ac9;
    padding: 20px;
    color: #fff;
    margin-left: 0;
    min-height: 250px;
    text-align: right;
}
.slide .slide-content .slide__label a {
    font-weight: 400;
    font-size: 18px;
    color: #ffc107;
}

.slide  .slide-content p a:focus {
    outline-color: #fff
}

.slide .slide-content .image-title h1 {
    font-size: 2.5em;
    color: #fff;
    font-weight: 400;
    margin: 0
}

.slide .slide-content hr {
    border-top: 1px solid #77a8e0;
    margin: 15px 0;
    opacity: 1
}

.slide .slide-content p a {
    color: #fff;
    font-size: 16px;
    display: inline-block;
    text-decoration: none;
    line-height: 1.6em;
}
.slide .slide-content p a:after {
    display: inline-block;
    font: 900 16px/1 "Font Awesome 5 Free";
    text-rendering: auto;
    -webkit-font-smoothing: antialiased;
    -moz-osx-font-smoothing: grayscale;
    content: '\f061';
    color: #7ba6d6;
    padding-left: 10px
}

.slide img{
    width: 100%;
    height: 100%;
    object-fit: cover;
    background-size: cover;
}

.slide__text {
    font-size: 40px;
    font-weight: bold;
    font-family: sans-serif;
}

.slider__nav a.slide__prev,
.slider__nav a.slide__next{
    background: none;
    border: 0;
    position: absolute;
    height: 100px!important;
    width: 50px!important;
    -webkit-transition: all 0.3s ease-in-out;
    -moz-transition: all 0.3s ease-in-out;
    -ms-transition: all 0.3s ease-in-out;
    -o-transition: all 0.3s ease-in-out;
    transition: all 0.3s ease-in-out;
    background-color: #fff;
    z-index: 9;
    counter-reset: #000;
}

.slider__nav a.slide__next{
    border-radius: 90px 0 0 90px;
}
.slider__nav a.slide__prev {
     border-radius:  0 90px 90px 0;
}

a.slide__prev,
.slider::before {
    left: 0;
}

a.slide__next,
.slider::after {
    right: 0;
    z-index: 99999999;
}

.slider::before,
.slider::after,
.slide__prev,
.slide__next {
position: relative;
}
.slide__next:after {
    content: "\f061";
    position: absolute;
    font: 900 16px/1 "Font Awesome 5 Free";
    padding: 3px;
    box-sizing: border-box;
    font-size: 30px;
    color: #0f4d92!important;
    top: 50%;
    transform: translateY(-50%);
    right: 0;
}
.slide__prev:after{
    content: "\f060";
    position: absolute;
    width: 35px;
    height: 35px;
    font: 900 16px/1 "Font Awesome 5 Free";
    padding: 3px;
    box-sizing: border-box;
    color: #0f4d92!important;
    font-size: 30px;
    left: 5px;
    top: 50%;
    transform: translateY(-50%);
}

.slider::before,
.slider::after {
  z-index: 1;
  background: none;
  pointer-events: none;
}

.slider__nav {
    display: flex;
}
.slider__nav__dots{
    box-sizing: border-box;
    position: absolute;
    bottom: 5%;
    right: 15%;
    width: 200px;
    text-align: center;
}

.slider__navlink {
    display: inline-block;
    width: 14px;
    height: 14px;
    padding: 0;
    border-radius: 50%;
    background: #fff;
    border: 1px solid #428bca;
    margin: 5px;
}
.slider__navlink:hover,
.slider__navlink.active{
    background: #ffc107;
    border: 2px solid #ffc107;
}


